export const calculateSummary = () => {
  const totalRecords = mockInsuranceData.length;
  const avgCharges = mockInsuranceData.reduce((sum, r) => sum + r.charges, 0) / totalRecords;
  const avgBMI = mockInsuranceData.reduce((sum, r) => sum + r.bmi, 0) / totalRecords;
  const smokerCount = mockInsuranceData.filter(r => r.smoker === 'yes').length;
  
  return {
    totalRecords,
    avgCharges: Math.round(avgCharges * 100) / 100,
    avgBMI: Math.round(avgBMI * 100) / 100,
    smokerCount
  };
};
